INSERT INTO facts VALUES(128,'slot-datamaking: model/ai_model_副本 was optimized on 2026-05-30 with GNN attention+residual, TemporalGRU history attention+scheduled sampling, SSIM+uncertainty multi-task loss, loss scale fixes, checkpoint dict config, and smoke/resume verification.','project','slot-datamaking,model,optimization',0.5,0,0,'2026-05-30 11:21:19','2026-05-30 11:21:19',NULL);
INSERT INTO facts VALUES(129,'slot-datamaking: ai_model_副本 model-structure review found two main risks: model.py scheduled sampling passes future interacted tokens as teachers (future-information leakage), and interaction.py GNN residual/GRU updates valid no-neighbor nodes instead of preserving them.','project','slot-datamaking,review,ai-model',0.5,0,0,'2026-05-30 11:55:33','2026-05-30 11:55:33',NULL);
INSERT INTO facts VALUES(130,'slot-datamaking ai_model_副本 second review found 1 Blocking, 6 Major/Minor issues; fixes applied: resume uses checkpoint config and skips autotune, scheduler/scaler saved, scheduled sampling future-token leak disabled, no-neighbor GNN preserves tokens, RGB unnormalize fixed, collision pos_weight applied, valid mask compositing fixed.','project','slot-datamaking,review,fixes',0.5,0,0,'2026-05-30 12:05:36','2026-05-30 12:05:36',NULL);
INSERT INTO facts VALUES(131,'telegrambots project uses centralized Telegram bot-to-bot manager with tmux_hermes backend: WSL/systemd starts five persistent Hermes tmux sessions (Supervisor, Planner, Researcher, Developer, Tester) with role-specific skills/MCP/toolsets from skill&mcp.md; Telegram service falls back to direct MiMo if tmux/Hermes fails.','project','telegrambots,hermes,tmux',0.599999999999999977,0,1,'2026-05-30 12:45:49','2026-05-30 12:45:59',NULL);
INSERT INTO facts VALUES(132,'telegrambots project documentation was expanded with environment variable table, system requirements, tmux/systemd operations, safety notes, troubleshooting, artifact cleanup guidance, and two scripts: scripts/cleanup_artifacts.py and scripts/uninstall_systemd_user_service.sh.','project','telegrambots,docs,ops',0.599999999999999977,0,1,'2026-05-30 12:59:18','2026-05-30 12:59:24',NULL);
INSERT INTO facts VALUES(133,'用户注意到 Hermes 在当前对话中没有主动使用 holographic memory 功能，而最近存储的事实（ID 128-132）都是 Codex 在执行代码任务时存储的。用户希望 Hermes 更主动地使用记忆功能来存储重要对话信息。','general','memory,对话,用户反馈',0.5,0,0,'2026-05-30 13:02:53','2026-05-30 13:02:53',NULL);
INSERT INTO facts VALUES(134,'系统提示中关于 holographic memory 的指导存在缺陷：1) 只说 "use fact_store to add facts" 但没有明确触发条件；2) persona 部分强调 session_search 和 skill_manage，但没有提到 holographic memory；3) 缺少像 "完成复杂任务后存储" 或 "用户表达偏好时存储" 这样的明确指导。这导致 AI 不知道什么时候应该主动使用记忆功能。','general','系统提示,记忆功能,改进建议',0.5,0,0,'2026-05-30 13:04:08','2026-05-30 13:04:08',NULL);
INSERT INTO facts VALUES(135,'建议改进 holographic memory 指导：1) 添加明确的触发条件，如 "在完成复杂任务后存储关键步骤和结果"；2) 在 persona 部分添加 "当用户表达偏好、反馈或重要信息时，使用 fact_store 存储"；3) 区分 session_search（回忆过去对话）和 holographic memory（存储结构化事实）的使用场景。','general','改进建议,系统提示,记忆功能',0.5,0,0,'2026-05-30 13:04:13','2026-05-30 13:04:13',NULL);
INSERT INTO facts VALUES(136,'Claude Code generated a modular review for telegrambots in claude-code-分模块审查.md. Key P0 findings: asyncio.gather can let one polling crash stop all bots; Supervisor fallback with fallback_role=DONE can mark failed dispatch as completed; HERMES_TMUX_YOLO needs explicit warning or removal.','project','telegrambots,review,claude-code',0.599999999999999977,0,1,'2026-05-30 13:04:47','2026-05-30 13:04:58',NULL);
INSERT INTO facts VALUES(137,'Codex 积极使用 holographic memory 的可能原因：1) 提示词工程更成熟，包含明确的使用指导和触发条件；2) 编码任务更复杂，更容易触发存储条件；3) 形成了正反馈循环（使用→获得好结果→继续使用）；4) 用户期望 Codex 记住更多信息。核心问题是 Hermes 的系统提示缺少明确指导，而 Codex 可能有更好的指导。','general','Codex,记忆功能,对比分析',0.5,0,0,'2026-05-30 13:05:38','2026-05-30 13:05:38',NULL);
INSERT INTO facts VALUES(138,'Codex AGENTS.md 包含详细的 holographic memory 使用指导，这是 Codex 积极使用记忆功能的根本原因。关键内容包括：1) 明确的自动写入触发条件（用户说"记住"→add，用户纠正→update，学到偏好/环境/项目信息→add，回答问题前→先search，使用记忆后→feedback）；2) 使用场景矩阵（具体用户问题→对应工具/动作）；3) 查询规则（回答特定主题前先search）；4) 反馈规则（使用记忆后调用feedback）。对比 Hermes 系统提示只有 "use fact_store to add facts" 一句话，缺少明确指导。','tool','AGENTS.md,holographic,memory,Codex,指导,对比',0.5,0,0,'2026-05-30 13:11:43','2026-05-30 13:11:43',NULL);
INSERT INTO facts VALUES(139,'telegrambots review fixes completed and validated: polling exceptions are isolated with TelegramError handling and gather(return_exceptions=True); Supervisor fallback errors now emit ERROR not DONE; SERVICE_LOCK_FILE prevents duplicate polling; code artifacts have 5MB/50MB defaults and 500MB hard cap; tmux marker parsing uses line-anchored regex with 16-hex job IDs; YOLO requires HERMES_TMUX_ALLOW_YOLO=I_UNDERSTAND; Windows startup now calls run_team.sh. Claude Code final review found no new P0/P1 issues.','project','telegrambots,review,fixes',0.599999999999999977,0,1,'2026-05-30 13:23:16','2026-05-30 13:23:25',NULL);
INSERT INTO facts VALUES(140,'telegrambots 项目说明 now documents a future mixed Agent backend design: current roles use tmux_hermes, future AgentRunner can route roles to TmuxHermesRunner, ClaudeCodeRunner, or DirectLLMRunner; recommended split is Supervisor/Planner/Researcher on Hermes and Developer/Tester on Claude Code. Temporary review files were removed.','project','telegrambots,docs,agent-backend',0.599999999999999977,0,1,'2026-05-30 13:40:03','2026-05-30 13:40:19',NULL);
INSERT INTO facts VALUES(141,'telegrambots 项目采用中心化 bot-to-bot 架构：worker 只响应消息开头为 [任务ID][Supervisor][ASSIGN] 的 Supervisor 派单；[DONE]/[ERROR] 或正文里的 @mention 不触发 worker。','project','telegrambots,bot2bot,supervisor',0.5,0,0,'2026-05-30 13:52:39','2026-05-30 13:52:39',NULL);
INSERT INTO facts VALUES(142,'telegrambots artifacts 目录中 B2B-20260530-214248 和 21:42-21:46 的 tmux-jobs 是之前 DONE 中 @ 触发循环时留下的调试/任务产物；22:09 后未观察到持续生成，当前门控修复后 worker 不应再被 DONE/@ 误触发。','project','telegrambots,artifacts,debug',0.5,0,0,'2026-05-30 14:13:10','2026-05-30 14:13:10',NULL);
INSERT INTO facts VALUES(143,'telegrambots 项目新增手机群聊可见性状态卡：Supervisor 发送 [STATUS] 任务卡，worker 收到派单后发送 [WORKING]，支持 /status 查询进行中任务；Claude Code 复审认为无阻塞问题，不会引入 bot 循环或破坏 ASSIGN 门控。','project','telegrambots,status,review',0.5,0,0,'2026-05-30 14:29:43','2026-05-30 14:29:43',NULL);
INSERT INTO facts VALUES(144,'telegrambots artifacts 布局已调整：任务产物写入 artifacts/tasks/B2B-*，Hermes tmux 调试文件保留在 artifacts/tmux-jobs，角色 prompt 保留在 artifacts/hermes-role-prompts；cleanup_artifacts.py 同时兼容清理新布局和旧版 artifacts/B2B-*。','project','telegrambots,artifacts,layout',0.5,0,0,'2026-05-30 14:41:07','2026-05-30 14:41:07',NULL);
INSERT INTO facts VALUES(145,'telegrambots worker 出站控制改为代码审核加重试：worker 生成非 [任务ID][角色][REPORT]、WORKING/STATUS/ASSIGN/DONE/ERROR、或 @其他 worker 时，服务拦截并把规则错误回灌给该 worker 重新输出一次；仍不合规才本地 fallback。send_as 仍保留硬门禁。','project','telegrambots,worker,guard,retry',0.5,0,0,'2026-05-30 15:02:44','2026-05-30 15:02:44',NULL);
INSERT INTO facts VALUES(146,'telegrambots 最终角色提示词与出站门禁：build_role_prompt 生成并注入 tmux，job JSON 携带 role_contract；worker 输出经 prepare_worker_report 审核，违规回灌重试一次；send_as 是主服务唯一 send_message 出口并对 worker enforce_worker_outbound；直接点名调度其他 worker 的 REPORT 正文也会被拦截。','project','telegrambots,prompt,guard,review',0.5,0,0,'2026-05-30 15:24:37','2026-05-30 15:24:37',NULL);
