INSERT INTO facts VALUES(151,'telegrambots 项目已恢复 run_team.sh 手动启动方案；当前 user systemd 服务 telegram-ai-team-bot2bot.service 已停止、disable 并移除，Windows 登录计划任务未找到。手动启动命令：cd /home/lzy/project/telegrambots && ./run_team.sh。','project','telegrambots,run_team,manual-start',0.650000000000000022,0,1,'2026-05-30 17:53:11','2026-05-30 18:14:21',NULL);
INSERT INTO facts VALUES(152,'telegrambots 修复了 Supervisor 对“你是谁”返回“任务 JSON 不完整”的问题：根因是 tmux Hermes job prompt 曾将超长 role_contract 放在 user_prompt 前面，模型误判截断。现在 job prompt 只发送当前任务 JSON 且优先包含 system_prompt/user_prompt，“你是谁”等身份问题本地直接回答，并拦截 Supervisor 对内部 prompt 不完整的伪 DONE。','project','telegrambots,bugfix,hermes',0.5,0,0,'2026-05-30 18:20:29','2026-05-30 18:20:29',NULL);
INSERT INTO facts VALUES(153,'telegrambots 的 tmux Hermes job 投递已改为路径模式：完整任务 payload 写入 artifacts/tmux-jobs/<job_id>.job.json，粘贴到 tmux 的 artifacts/tmux-jobs/<job_id>.prompt.txt 只包含任务文件路径、角色契约文件路径和输出标记；Supervisor toolsets 已加入 file 以便读取任务文件。','project','telegrambots,hermes,prompt',0.5,0,0,'2026-05-30 18:22:11','2026-05-30 18:22:11',NULL);
INSERT INTO facts VALUES(154,'telegrambots/code current bugfix state: Bot initialization passes custom HTTPXRequest to both request and get_updates_request with TELEGRAM_CONNECTION_POOL_SIZE default 16; initial user total task dispatch to Supervisor Hermes tmux prefixes the job prompt with /goal via goal_mode=True in manager_start_task only; subsequent Supervisor decisions from worker REPORTs do not use /goal; completed tasks reopen on later worker REPORT as a safety fallback.','project','telegrambots,bugfix,polling,goal',0.5,0,0,'2026-05-31 03:50:11','2026-05-31 04:33:41',NULL);
INSERT INTO facts VALUES(155,'telegrambots/run.sh now acts as a restart script: if data/bot2bot.lock points to a live bot2bot service PID, it sends SIGTERM, waits up to 15s, SIGKILLs if needed, removes the lock, stops only telegrambots Hermes tmux role sessions via scripts/stop_hermes_tmux_agents.py, then starts fresh sessions and execs python3 -m bot2bot.service.','project','telegrambots,runsh,restart',0.5,0,0,'2026-05-31 04:39:44','2026-05-31 04:39:44',NULL);
INSERT INTO facts VALUES(156,'slot-datamaking/model 的 promptv1 是研究规划任务，promptv2 是实现 10 个实验任务；一次验收发现 experiments 目录已生成，但存在 ai_model 被修改、config_override 未被训练脚本使用、部分新增 loss 未加入 total_loss、scheduled sampling 泄漏未来 token 等问题。','project','slot-datamaking,experiments,prompts',0.5,0,0,'2026-05-31 14:17:11','2026-05-31 14:17:11',NULL);
INSERT INTO facts VALUES(157,'slot-datamaking/model experiments vs current ai_model comparison: exp003_more_physics_features has the clearest measured gain (-5.1% val loss vs experiments baseline); exp001 LPIPS is a plausible RGB optimization if lpips is installed; exp002 and exp007 compute extra losses but do not add them to total_loss; exp004 scheduled sampling leaks future interacted tokens; exp006 curriculum only adds compute_complexity and is not used by train; exp008/009/010 are high-risk prototype architecture branches.','project','slot-datamaking,experiments,evaluation',0.5,0,0,'2026-05-31 14:21:11','2026-05-31 14:21:11',NULL);
INSERT INTO facts VALUES(158,'slot-datamaking/model/ai_model 已融合低风险优化：PhysicsEncoder 增加 KE/PE/动量/角动量派生特征，默认 GNN 层数改为 3，GNN attention mask 改为 FP16-safe -1e4，可选 LPIPS loss，能量守恒 loss 和 collision_effect 辅助头/loss 已真正加入 total_loss；DINO/Mamba/Slot/Scheduled Sampling 未合入主线。','project','slot-datamaking,ai_model,optimization',0.5,0,0,'2026-05-31 14:30:14','2026-05-31 14:30:14',NULL);
INSERT INTO facts VALUES(159,'slot-datamaking/model 已更新 ROADMAP：主线 ai_model 作为优化版维护，Scheduled Sampling、DINOv2、Mamba、Slot Attention/SAVi 作为暂缓大分支保留实现要求；ai_model/train.py 已接入 TensorBoard SummaryWriter，默认写 model/runs，6006 可视化服务已验证可访问。','project','slot-datamaking,roadmap,tensorboard',0.5,0,0,'2026-05-31 14:38:33','2026-05-31 14:38:33',NULL);
INSERT INTO facts VALUES(160,'slot-datamaking/model/ai_model TensorBoard 标量标签已改为中文分组（训练/每步、训练/每轮、验证/每轮、模型），ROADMAP.md 已加入每个中文标签含义和查看顺序；旧 event 文件仍保留英文标签，新训练日志会显示中文。','project','slot-datamaking,tensorboard,roadmap',0.5,0,0,'2026-05-31 14:48:44','2026-05-31 14:48:44',NULL);
